/* Read-only public market adapters. No credentials or trading endpoints. */
(function(root){
const BAR=300000,n=v=>v===null||v===undefined||v===''?null:Number.isFinite(Number(v))?Number(v):null;
const positive=v=>{v=n(v);return v>0?v:null;};
const spread=(b,a)=>b>0&&a>=b?(a-b)/((a+b)/2)*10000:null;
const knownTradfiNames=/^(Silver|Gold|Swap on (Gold|Silver) Spot|Meta Platforms, Inc\.|Intel Corporation|Microsoft Corporation|Tesla, Inc\.|Apple Inc\.|Oracle Corporation|Alphabet Inc\.|Advanced Micro Devices, Inc\.|SK hynix Inc\.|Strategy Inc|Sandisk Corporation|Micron Technology, Inc\.|Robinhood Markets, Inc\.|NVIDIA Corporation|Coinbase Global, Inc\.|Invesco QQQ Trust, Series 1)$/;
function normalize(venue,data,config){
 if(venue==='Arcus')return data.markets.map(r=>({id:r.marketDisplayName,symbol:r.marketDisplayName,name:r.fullAssetName,type:r.type,tradfi:r.category!=='CRYPTO',category:r.category,status:r.status,price:positive(r.markPrice),bid:null,ask:null,spread:null,volume:n(r.volume24hNotional),quoteTime:null,funding:n(r.fundingRate),fundingLabel:'Reported rate (interval unverified)',fundingSeconds:null,takerBps:n(r.effectiveTakerFeePpm)===null?null:n(r.effectiveTakerFeePpm)/100,offHours:r.isOutsideRth===true}));
 if(venue==='Variational')return data.listings.map(r=>{const q=r.quotes?.size_1k||r.quotes?.base||{},f=r.funding,rate=f?.next||f?.last;return {id:r.ticker,symbol:r.ticker,name:r.name,type:r.contract_type,tradfi:knownTradfiNames.test(r.name),category:knownTradfiNames.test(r.name)?'Verified TradFi shortlist':'Other / unclassified',status:'Listed',price:positive(r.mark_price),bid:positive(q.bid),ask:positive(q.ask),spread:spread(positive(q.bid),positive(q.ask)),volume:n(r.volume_24h),quoteTime:Date.parse(r.quotes?.updated_at)||null,funding:r.contract_type==='perpetual'?n(f?.last?.interval_rate):null,fundingLong:r.contract_type==='swap'?n(rate?.interval_long_rate):null,fundingShort:r.contract_type==='swap'?n(rate?.interval_short_rate):null,fundingLabel:r.contract_type==='swap'?'Swap payment: long pays / short receives':'Per funding interval',fundingSeconds:n(f?.interval_seconds),nextFunding:n(f?.next_timestamp),fundingStage:f?.next?'next':'last',takerBps:null};});
 if(String(data.code)!=='200'||String(config?.code)!=='200')throw Error('Popdex rejected the market request.');
 const by=new Map(data.data.map(r=>[r.symbol,r]));return config.data.map(c=>{const r=by.get(c.symbol)||{};return {id:c.symbol,symbol:c.symbol,name:c.baseToken,type:c.category,tradfi:c.assetClass==='Rwa',category:c.assetClass,status:r.status||c.status,price:positive(r.markPrice),bid:positive(r.bid1Price),ask:positive(r.ask1Price),spread:spread(positive(r.bid1Price),positive(r.ask1Price)),volume:n(r.turnover24h),quoteTime:positive(r.updatedTime),funding:n(r.fundingRate),fundingLabel:'Reported rate (interval unverified)',fundingSeconds:null,takerBps:n(c.feeRates?.find(f=>f.vipLevel==='0')?.takerFeeRate)===null?null:n(c.feeRates.find(f=>f.vipLevel==='0').takerFeeRate)*10000,session:c.tradingSessions?.find(s=>Date.now()>=+s.startMs&&Date.now()<+s.endMs)?.sessionType||null};});
}
function candles(venue,data,now=Date.now()){
 const rows=venue==='Arcus'?data.candles:data.data;if(!Array.isArray(rows))throw Error('Unexpected candle response.');if(venue==='Popdex'&&String(data.code)!=='200')throw Error(data.msg||'Candle request failed.');const map=new Map;for(const r of rows){const t=venue==='Arcus'?n(r.openTime)/1000:n(r[0]),c=positive(venue==='Arcus'?r.close:r[4]);if(!Number.isSafeInteger(t)||t%BAR!==0||c===null||t+BAR>now-2000||venue==='Arcus'&&r.isFinal!==true)continue;map.set(t,{t,c,volume:n(venue==='Arcus'?r.volume:r[5])});}return [...map.values()].sort((a,b)=>a.t-b.t);
}
function align(a,b){const bm=new Map(b.map(r=>[r.t,r]));return a.filter(r=>bm.has(r.t)).map(r=>({t:r.t,a:r.c,b:bm.get(r.t).c}));}
async function get(url){const r=await fetch(url,{credentials:'omit',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error(r.status===429?'Rate limited. Wait at least one minute before refreshing.':`Market request failed (${r.status}).`);return r.json();}
async function markets(venue){let data,config;if(venue==='Arcus')data=await get('https://api.arcus.xyz/v1/markets');else if(venue==='Variational')data=await get('https://omni-client-api.prod.ap-northeast-1.variational.io/metadata/v2/stats');else {if(location.protocol==='file:')throw Error('Open Start Pairdesk.command to connect Popdex through the local relay.');[data,config]=await Promise.all([get('/api/popdex/tickers'),get('/api/popdex/symbols')]);}return {rows:normalize(venue,data,config),fetched:Date.now(),total:venue==='Popdex'?n(data.total):null,coverage:venue==='Popdex'?data.data.length:null};}
async function history(venue,symbol){if(venue==='Variational')throw Error('Variational public API provides snapshots, not verified historical candles.');const url=venue==='Arcus'?'https://api.arcus.xyz/v1/candles?'+new URLSearchParams({market:symbol,timeframe:'5m',to:String(Date.now()*1000),countback:'1500'}):'/api/popdex/candles?'+new URLSearchParams({symbol});return candles(venue,await get(url));}
root.MarketFeeds={normalize,candles,align,markets,history};if(typeof module!=='undefined')module.exports=root.MarketFeeds;
})(typeof globalThis!=='undefined'?globalThis:this);
